class Solution { public String digitSum(String s, int k) { while (s.length() > k) { StringBuilder t = new StringBuilder(); int n = s.length(); for (int i = 0; i < n; i += k) { int x = 0; for (int j = i; j < i + k && j < n; j++) x += s.charAt(j) - '0'; t.append(x); } s = t.toString(); } return s; } }